<script setup lang="ts">
import { onMounted, ref } from "vue";import { ClipboardList } from "lucide-vue-next";import H5Header from "../components/H5Header.vue";import { cancelServiceOrder, fetchServiceOrders, type ServiceOrder } from "../api";
const orders=ref<ServiceOrder[]>([]);const error=ref("");const loading=ref(true);const labels:Record<string,string>={PENDING_PAYMENT:"待支付",PAID:"已支付",CONFIRMED:"已确认",SERVING:"服务中",COMPLETED:"已完成",CANCELLED:"已取消",REFUNDING:"退款处理中",REFUNDED:"已退款"};
async function load(){if(!localStorage.getItem("jianda_resident_token")){location.assign(`/resident/login?redirect=${encodeURIComponent('/orders')}`);return;}try{orders.value=await fetchServiceOrders();}catch(e:any){error.value=e?.response?.data?.message||"订单暂时无法读取。";}finally{loading.value=false;}}
async function cancel(item:ServiceOrder){if(!window.confirm("确认取消这个待支付订单吗？"))return;try{await cancelServiceOrder(item.id);await load();}catch(e:any){error.value=e?.response?.data?.message||"订单无法取消。";}}onMounted(load);
</script>
<template><div class="h5-page"><H5Header/><main class="h5-main service-orders"><header class="app-section-head"><ClipboardList/><div><h1>我的订单</h1><p>合作服务订单与政府公开信息分开管理。</p></div></header><p class="payment-note">线上支付未配置时，订单会保持“待支付”，不会自动变成已支付。</p><p v-if="error" class="form-error">{{error}}</p><div v-if="loading" class="list-skeleton"><i v-for="n in 2" :key="n"/></div><section v-else><article v-for="item in orders" :key="item.id"><header><b>{{item.product_name}}</b><span>{{labels[item.status]||item.status}}</span></header><p>{{item.provider_name}} · 数量 {{item.quantity}}</p><strong>¥{{(item.amount_cents/100).toFixed(2)}}</strong><small>订单号 {{item.order_no}}</small><button v-if="item.status==='PENDING_PAYMENT'" @click="cancel(item)">取消订单</button></article><div v-if="!orders.length" class="empty"><ClipboardList/><b>还没有服务订单</b><RouterLink to="/trusted-services">查看已核验合作服务</RouterLink></div></section></main></div></template>
<style scoped>.payment-note{padding:14px;background:#f3f5f4}.service-orders section{display:grid;gap:12px}.service-orders article{display:grid;gap:8px;padding:18px;background:white;border:1px solid #d9e1de}.service-orders header{display:flex;justify-content:space-between}.service-orders header span{color:#9a5716}.service-orders small{overflow-wrap:anywhere}.service-orders button{justify-self:start;min-height:48px;padding:0 18px}</style>
